/**
 @file  mtu.c
 @brief ENet authenticated path MTU discovery
*/
#include <stdio.h>
#include <string.h>
#define ENET_BUILDING_LIB 1
#include "enet/utility.h"
#include "enet/time.h"
#include "enet/enet.h"

/** @defgroup mtu ENet path MTU discovery functions
    @{
*/

/* FNV-1a 32-bit, used to authenticate probe/ack cookies. It is keyed by the
 * connection id, which is randomly generated by the connecting host, exchanged
 * in the (unchanged) handshake and identical on both ends, and unknown to an
 * off-path attacker. When the application also enables ENet's datagram
 * checksums the probes are independently protected by that checksum as well.
 * This is not a cryptographic MAC, but it ties every probe to an unguessable
 * per-connection value, which is sufficient against off-path injection of
 * acknowledgements that could otherwise shrink a peer's MTU. */
static enet_uint32
enet_mtu_hash_step (enet_uint32 hash, enet_uint32 value)
{
    int i;

    for (i = 0; i < 4; ++ i)
    {
        hash ^= (enet_uint8) (value & 0xFF);
        hash *= 16777619u;
        value >>= 8;
    }

    return hash;
}

static enet_uint32
enet_mtu_cookie (ENetPeer * peer, enet_uint32 probeMtu, enet_uint32 nonce)
{
    enet_uint32 hash = 2166136261u;

    hash = enet_mtu_hash_step (hash, peer -> connectID);
    hash = enet_mtu_hash_step (hash, probeMtu);
    hash = enet_mtu_hash_step (hash, nonce);

    return hash;
}

static enet_uint32
enet_mtu_align (enet_uint32 value)
{
    return value - (value % ENET_MTU_ALIGNMENT);
}

static enet_uint32
enet_mtu_clamp (ENetHost * host, enet_uint32 value)
{
    if (value < ENET_PROTOCOL_MINIMUM_MTU)
      return ENET_PROTOCOL_MINIMUM_MTU;

    if (value > host -> mtuConfig.maxMtu)
      return host -> mtuConfig.maxMtu;

    return value;
}

static void
enet_mtu_diag (ENetPeer * peer, const char * message, enet_uint32 value)
{
#ifdef ENET_DEBUG
    printf ("peer %u: PMTUD %s (mtu=%u value=%u state=%d)\n",
            peer -> incomingPeerID, message, peer -> mtu, value, peer -> mtuDiscovery.state);
#else
    (void) peer;
    (void) message;
    (void) value;
#endif
}

void
enet_mtu_initialize_host (ENetHost * host)
{
    memset (& host -> mtuConfig, 0, sizeof (host -> mtuConfig));
    host -> mtuConfig.allowFragmentation = 1;
}

void
enet_mtu_initialize_peer (ENetPeer * peer)
{
    memset (& peer -> mtuDiscovery, 0, sizeof (peer -> mtuDiscovery));
    peer -> mtuDiscovery.state = ENET_MTU_STATE_DISABLED;
}

void
enet_mtu_reset_peer (ENetPeer * peer)
{
    ENetMtuDiscovery * discovery = & peer -> mtuDiscovery;
    int enabled = peer -> host != NULL && peer -> host -> mtuConfig.enabled;

    memset (discovery, 0, sizeof (* discovery));

    if (! enabled)
    {
        discovery -> state = ENET_MTU_STATE_DISABLED;
        return;
    }

    discovery -> state = ENET_MTU_STATE_IDLE;
    discovery -> baseMtu = ENET_PROTOCOL_MINIMUM_MTU;
    discovery -> maxMtu = enet_mtu_clamp (peer -> host, peer -> host -> mtuConfig.maxMtu);
    discovery -> probeLow = ENET_PROTOCOL_MINIMUM_MTU;
    discovery -> probeHigh = discovery -> maxMtu + 1;
    discovery -> probeMtu = 0;
    discovery -> nextProbeTime = 0;
    discovery -> blackHoleUntil = 0;
    discovery -> floorProbed = 0;
    discovery -> revalidating = 0;
}

/* Applies a new confirmed MTU to the peer and requests re-segmentation of any
 * queued packets that no longer fit. Never raises above the current value
 * without an authenticated acknowledgement. */
static void
enet_mtu_apply (ENetPeer * peer, enet_uint32 newMtu)
{
    ENetMtuDiscovery * discovery = & peer -> mtuDiscovery;

    newMtu = enet_mtu_clamp (peer -> host, newMtu);

    if (newMtu == peer -> mtu)
      return;

    if (newMtu < peer -> mtu)
    {
        ++ discovery -> stats.mtuDecreases;
        /* Existing queued/fragmented packets must be re-cut to the smaller size. */
        discovery -> resegmentPending = 1;
    }
    else
    {
        ++ discovery -> stats.mtuIncreases;
    }

    enet_mtu_diag (peer, "MTU change", newMtu);
    peer -> mtu = newMtu;
}

int
enet_host_enable_mtu_discovery (ENetHost * host, const ENetMtuConfig * config)
{
    ENetMtuConfig * current = & host -> mtuConfig;
    ENetPeer * peer;

    if (config == NULL)
    {
        memset (current, 0, sizeof (* current));
        current -> allowFragmentation = 1;

        for (peer = host -> peers; peer < & host -> peers [host -> peerCount]; ++ peer)
        {
            peer -> mtuDiscovery.state = ENET_MTU_STATE_DISABLED;
            peer -> mtuDiscovery.resegmentPending = 0;
            if (peer -> state == ENET_PEER_STATE_DISCONNECTED)
              peer -> mtu = host -> mtu;
        }

        return 0;
    }

    if (config -> maxMtu != 0 &&
        (config -> maxMtu < ENET_PROTOCOL_MINIMUM_MTU || config -> maxMtu > ENET_PROTOCOL_MAXIMUM_MTU))
      return -1;

    * current = * config;

    if (current -> maxMtu == 0 || current -> maxMtu > host -> mtu)
      current -> maxMtu = host -> mtu;

    if (current -> probeTimeout == 0)
      current -> probeTimeout = ENET_MTU_DEFAULT_PROBE_TIMEOUT;
    else
    if (current -> probeTimeout < ENET_MTU_MIN_PROBE_TIMEOUT)
      current -> probeTimeout = ENET_MTU_MIN_PROBE_TIMEOUT;
    else
    if (current -> probeTimeout > ENET_MTU_MAX_PROBE_TIMEOUT)
      current -> probeTimeout = ENET_MTU_MAX_PROBE_TIMEOUT;

    if (current -> maxProbeAttempts == 0)
      current -> maxProbeAttempts = ENET_MTU_DEFAULT_MAX_PROBE_ATTEMPTS;

    if (current -> blackHoleBackoff == 0)
      current -> blackHoleBackoff = ENET_MTU_DEFAULT_BLACK_HOLE_BACKOFF;

    if (current -> revalidateTime == 0)
      current -> revalidateTime = ENET_MTU_DEFAULT_REVALIDATE_TIME;

    /* Peers that have never connected pick the configuration up through
     * enet_mtu_reset_peer(); connected peers are left untouched until an
     * explicit enet_peer_start_mtu_discovery() call. */
    for (peer = host -> peers; peer < & host -> peers [host -> peerCount]; ++ peer)
    {
        if (peer -> state == ENET_PEER_STATE_DISCONNECTED)
          enet_mtu_reset_peer (peer);
    }

    return 0;
}

int
enet_peer_get_mtu_stats (ENetPeer * peer, ENetMtuStats * stats)
{
    if (peer == NULL || stats == NULL)
      return -1;

    * stats = peer -> mtuDiscovery.stats;
    return 0;
}

int
enet_peer_start_mtu_discovery (ENetPeer * peer)
{
    if (peer == NULL || ! peer -> host -> mtuConfig.enabled)
      return -1;

    if (peer -> state != ENET_PEER_STATE_CONNECTED &&
        peer -> state != ENET_PEER_STATE_CONNECTION_PENDING &&
        peer -> state != ENET_PEER_STATE_CONNECTION_SUCCEEDED &&
        peer -> state != ENET_PEER_STATE_DISCONNECT_LATER)
      return -1;

    /* Start the search from the safe floor so an oversized-MTU black hole can
     * never strand an in-flight handshake or queued reliable traffic. */
    enet_mtu_reset_peer (peer);
    enet_mtu_apply (peer, ENET_PROTOCOL_MINIMUM_MTU);
    peer -> mtuDiscovery.state = ENET_MTU_STATE_IDLE;
    peer -> mtuDiscovery.nextProbeTime = 0;

    return 0;
}

void
enet_mtu_on_connect (ENetPeer * peer)
{
    if (! peer -> host -> mtuConfig.enabled)
      return;

    enet_mtu_reset_peer (peer);
    enet_mtu_apply (peer, ENET_PROTOCOL_MINIMUM_MTU);
    peer -> mtuDiscovery.state = ENET_MTU_STATE_IDLE;
}

/* Picks the next candidate with an 8-byte-aligned binary search between the
 * confirmed lower bound (probeLow) and the failing upper bound (probeHigh).
 *
 * The safe floor is the initial confirmed lower bound, so on a healthy path it
 * is never re-probed and the search converges normally. When every candidate
 * above the floor fails, the descending search eventually returns the floor as
 * a candidate: if that probe also fails, the caller treats it as a black hole
 * (the minimum MTU itself cannot pass) and enters back-off. Returns 0 when the
 * search has fully converged. */
static enet_uint32
enet_mtu_next_candidate (ENetPeer * peer)
{
    ENetMtuDiscovery * discovery = & peer -> mtuDiscovery;
    enet_uint32 span, midpoint;

    if (discovery -> probeHigh <= discovery -> probeLow)
      return 0;

    span = discovery -> probeHigh - discovery -> probeLow;

    /* No room for a distinct aligned candidate between the bounds. */
    if (span <= ENET_MTU_ALIGNMENT)
      return 0;

    midpoint = discovery -> probeLow + span / 2;
    midpoint = enet_mtu_align (midpoint);

    if (midpoint <= discovery -> probeLow || midpoint >= discovery -> probeHigh)
      return 0;

    return enet_mtu_clamp (peer -> host, midpoint);
}

/* Returns the byte offset at which the first command begins in a probe/ack
 * datagram, writing the 2-byte ENet peer header. This mirrors the framing used
 * by enet_protocol_send_outgoing_commands(): when a checksum is configured the
 * 4-byte checksum field sits between the header and the commands, and the
 * receiver's generic parser authenticates the whole datagram before dispatch.
 * The checksum itself is written by enet_mtu_finalize_checksum() once the
 * command body is in place, so it always covers the complete datagram. */
static size_t
enet_mtu_command_offset (ENetHost * host, ENetPeer * peer, enet_uint8 * data)
{
    size_t offset = ENET_OFFSETOF (ENetProtocolHeader, sentTime);
    ENetProtocolHeader * header = (ENetProtocolHeader *) data;
    enet_uint16 peerID = peer -> outgoingPeerID;

    if (peer -> outgoingPeerID < ENET_PROTOCOL_MAXIMUM_PEER_ID)
      peerID |= (enet_uint16) (peer -> outgoingSessionID << ENET_PROTOCOL_HEADER_SESSION_SHIFT);
    header -> peerID = ENET_HOST_TO_NET_16 (peerID);

    if (host -> checksum != NULL)
      offset += sizeof (enet_uint32);

    return offset;
}

/* Computes and writes the datagram checksum over the full (padded) datagram.
 * Mirrors ENet's convention of placing the connect id in the checksum slot
 * while the hash is computed. No-op when checksums are disabled. */
static void
enet_mtu_finalize_checksum (ENetHost * host, ENetPeer * peer, enet_uint8 * data, size_t totalLength)
{
    if (host -> checksum == NULL)
      return;

    {
        ENetBuffer buffer;
        enet_uint32 checksum;
        enet_uint8 * slot = data + ENET_OFFSETOF (ENetProtocolHeader, sentTime);

        buffer.data = data;
        buffer.dataLength = totalLength;

        memcpy (slot, & peer -> connectID, sizeof (enet_uint32));
        checksum = host -> checksum (& buffer, 1);
        memcpy (slot, & checksum, sizeof (enet_uint32));
    }
}

/* Builds and sends a probe datagram from the host scratch buffer. No heap
 * allocation happens on the probe path. */
static void
enet_mtu_send_probe (ENetHost * host, ENetPeer * peer, enet_uint32 probeMtu, enet_uint32 now)
{
    ENetMtuDiscovery * discovery = & peer -> mtuDiscovery;
    ENetBuffer buffer;
    ENetProtocolMtuProbe * probe;
    enet_uint8 * data = host -> mtuProbeData;
    size_t probeSize = sizeof (ENetProtocolMtuProbe);
    enet_uint32 nonce = enet_host_random (host);
    enet_uint32 cookie;
    size_t headerSize;

    if (probeMtu > ENET_PROTOCOL_MAXIMUM_MTU || probeMtu < ENET_PROTOCOL_MINIMUM_MTU)
      return;

    cookie = enet_mtu_cookie (peer, probeMtu, nonce);

    /* Zero padding for the full candidate datagram; the checksum (if any)
     * covers these deterministic zero bytes as well. */
    memset (data, 0, probeMtu);

    headerSize = enet_mtu_command_offset (host, peer, data);

    if (headerSize + probeSize > probeMtu)
      return;

    /* Probes are unreliable and never acknowledged through the normal
     * reliable-command machinery. */
    probe = (ENetProtocolMtuProbe *) (data + headerSize);
    probe -> header.command = ENET_PROTOCOL_COMMAND_MTU_PROBE;
    probe -> header.channelID = 0xFF;
    probe -> header.reliableSequenceNumber = 0;
    probe -> cookie = ENET_HOST_TO_NET_32 (cookie);
    probe -> probeMtu = ENET_HOST_TO_NET_32 (probeMtu);
    probe -> nonce = ENET_HOST_TO_NET_32 (nonce);

    enet_mtu_finalize_checksum (host, peer, data, probeMtu);

    buffer.data = data;
    buffer.dataLength = probeMtu;

    if (enet_socket_send (host -> socket, & peer -> address, & buffer, 1) < 0)
    {
        enet_mtu_diag (peer, "probe socket send failed", probeMtu);
        return;
    }

    host -> totalSentData += probeMtu;
    ++ host -> totalSentPackets;

    discovery -> state = ENET_MTU_STATE_PROBING;
    discovery -> probeMtu = probeMtu;
    discovery -> probeNonce = nonce;
    discovery -> probeCookie = cookie;
    discovery -> nextProbeTime = now + host -> mtuConfig.probeTimeout;
    discovery -> stats.probesSent ++;
    discovery -> stats.lastProbeMtu = probeMtu;
    discovery -> stats.currentProbeMtu = probeMtu;
}

static void
enet_mtu_converge (ENetPeer * peer, enet_uint32 now)
{
    ENetMtuDiscovery * discovery = & peer -> mtuDiscovery;
    ENetHost * host = peer -> host;

    discovery -> state = ENET_MTU_STATE_CONVERGED;
    discovery -> probeMtu = 0;
    discovery -> stats.currentProbeMtu = 0;
    discovery -> nextRevalidateTime = host -> mtuConfig.revalidateTime ?
                                       now + host -> mtuConfig.revalidateTime : 0;
    enet_mtu_diag (peer, "search converged", peer -> mtu);
}

/* A probe candidate was declared too large after all retries were exhausted. */
static void
enet_mtu_probe_failed (ENetHost * host, ENetPeer * peer, enet_uint32 now)
{
    ENetMtuDiscovery * discovery = & peer -> mtuDiscovery;
    int wasRevalidating = discovery -> revalidating;

    discovery -> revalidating = 0;
    discovery -> stats.probesLost += discovery -> probeAttempts;

    if (discovery -> probeMtu < discovery -> probeHigh)
      discovery -> probeHigh = discovery -> probeMtu;

    /* A failed probe at or below the safe floor means even the minimum MTU does
     * not traverse the path: a genuine black hole. Hold the minimum MTU, keep
     * the connection alive on previously confirmed traffic, and back off before
     * re-probing the floor. */
    if (discovery -> probeMtu <= discovery -> baseMtu)
    {
        discovery -> state = ENET_MTU_STATE_BLACK_HOLE;
        discovery -> blackHoleUntil = now + host -> mtuConfig.blackHoleBackoff;
        discovery -> nextProbeTime = discovery -> blackHoleUntil;
        discovery -> probeMtu = 0;
        discovery -> probeAttempts = 0;
        discovery -> floorProbed = 0;
        discovery -> stats.currentProbeMtu = 0;
        ++ discovery -> stats.blackHoleEvents;
        enet_mtu_apply (peer, discovery -> baseMtu);
        enet_mtu_diag (peer, "black hole, backed off to safe MTU", peer -> mtu);
        return;
    }

    /* A failed revalidation of a previously converged MTU means the path
     * shrank: reopen the search underneath the now-too-large value and step the
     * live MTU down so queued traffic is re-segmented to a safe size. */
    if (wasRevalidating)
    {
        discovery -> probeHigh = discovery -> probeMtu;
        discovery -> probeLow = discovery -> baseMtu;
        discovery -> floorProbed = 0;
        enet_mtu_apply (peer, discovery -> baseMtu);
    }

    discovery -> state = ENET_MTU_STATE_IDLE;
    discovery -> probeMtu = 0;
    discovery -> probeAttempts = 0;
    discovery -> stats.currentProbeMtu = 0;
    discovery -> nextProbeTime = now;
}

/* Re-segment the queued outgoing commands of a peer after its MTU changed.
 *
 * Every command carrying packet data is first detached into a private list, so
 * re-created commands produced by enet_peer_send() (which go back into the
 * peer's regular queues) can never be collected again and loop. Each packet's
 * reference count is then unwound and the packet re-fed to enet_peer_send(),
 * which re-fragments against the new MTU. Reliable sequence numbers and window
 * accounting of the removed commands are rolled back so the recreated fragments
 * reuse the same reliable range. Commands without packets (pings, acks,
 * connect, ...) are untouched. */
static void
enet_mtu_resegment (ENetPeer * peer)
{
    ENetHost * host = peer -> host;
    ENetList * queues [3];
    ENetList collected;
    ENetListIterator it;
    ENetOutgoingCommand * command;
    ENetPacket * packet;
    enet_uint8 channelID;
    enet_uint32 flags;
    int queueIndex;
    size_t count;

    enet_list_clear (& collected);
    queues [0] = & peer -> outgoingCommands;
    queues [1] = & peer -> outgoingSendReliableCommands;
    queues [2] = & peer -> sentReliableCommands;

    /* Phase 1: detach every data-carrying command into the private list. The
     * regular queues now hold only control commands, so re-insertion during the
     * re-send phase cannot feed back into this collection. */
    for (queueIndex = 0; queueIndex < 3; ++ queueIndex)
    {
        for (it = enet_list_begin (queues [queueIndex]);
             it != enet_list_end (queues [queueIndex]);)
        {
            command = (ENetOutgoingCommand *) it;
            it = enet_list_next (it);

            if (command -> packet == NULL)
              continue;

            enet_list_remove (& command -> outgoingCommandList);
            enet_list_insert (enet_list_end (& collected), command);
        }
    }

    if (enet_list_empty (& collected))
    {
        peer -> mtuDiscovery.resegmentPending = 0;
        return;
    }

    /* Phase 2: group the detached commands by packet, release the old fragments
     * (rolling back their reliable bookkeeping), then re-send each packet so it
     * is re-fragmented against the new MTU. */
    while (! enet_list_empty (& collected))
    {
        ENetOutgoingCommand * first = (ENetOutgoingCommand *) enet_list_front (& collected);
        packet = first -> packet;
        channelID = first -> command.header.channelID;
        flags = packet -> flags;
        count = 0;

        for (it = enet_list_begin (& collected); it != enet_list_end (& collected);)
        {
            command = (ENetOutgoingCommand *) it;
            it = enet_list_next (it);

            if (command -> packet != packet ||
                command -> command.header.channelID != channelID)
              continue;

            enet_list_remove (& command -> outgoingCommandList);

            /* Roll back reliable window/sequence bookkeeping for reliable
             * fragments that were already assigned sequence numbers. */
            if ((command -> command.header.command & ENET_PROTOCOL_COMMAND_FLAG_ACKNOWLEDGE) &&
                channelID < peer -> channelCount &&
                command -> sendAttempts > 0)
            {
                ENetChannel * channel = & peer -> channels [channelID];
                enet_uint16 reliableWindow = command -> reliableSequenceNumber / ENET_PEER_RELIABLE_WINDOW_SIZE;

                if (channel -> reliableWindows [reliableWindow] > 0)
                {
                    -- channel -> reliableWindows [reliableWindow];
                    if (! channel -> reliableWindows [reliableWindow])
                      channel -> usedReliableWindows &= ~ (1u << reliableWindow);
                }

                peer -> reliableDataInTransit -= ENET_MIN (peer -> reliableDataInTransit,
                                                            command -> fragmentLength);
            }

            peer -> outgoingDataTotal -= ENET_MIN (peer -> outgoingDataTotal,
                                                   enet_protocol_command_size (command -> command.header.command) +
                                                   command -> fragmentLength);

            -- packet -> referenceCount;
            enet_free (command);
            ++ count;
        }

        /* Rewind the channel's reliable sequence number by the number of
         * reliable commands removed, so recreated fragments reuse the range and
         * the remote peer sees no gaps. Unreliable/unsequenced channels are not
         * rewound: their sequence numbers are allowed to skip. */
        if ((flags & ENET_PACKET_FLAG_RELIABLE) && channelID < peer -> channelCount)
        {
            ENetChannel * channel = & peer -> channels [channelID];
            channel -> outgoingReliableSequenceNumber =
                (enet_uint16) (channel -> outgoingReliableSequenceNumber - (enet_uint16) count);
        }

        /* Keep the packet alive across enet_peer_send(), then drop this
         * reference. When fragmentation is disabled the packet no longer fits:
         * hold it back instead of destroying it so it can be sent once the MTU
         * recovers, unless it can never fit at all. */
        ++ packet -> referenceCount;

        if (! host -> mtuConfig.allowFragmentation &&
            packet -> dataLength > (peer -> mtu - sizeof (ENetProtocolHeader) - sizeof (ENetProtocolSendFragment) -
                                    (host -> checksum != NULL ? sizeof (enet_uint32) : 0)))
        {
            -- packet -> referenceCount;

            if (packet -> referenceCount == 0)
            {
                packet -> flags |= ENET_PACKET_FLAG_SENT;
                enet_packet_destroy (packet);
            }
            continue;
        }

        if (enet_peer_send (peer, channelID, packet) < 0)
          enet_mtu_diag (peer, "re-segmentation rejected packet", (enet_uint32) packet -> dataLength);

        -- packet -> referenceCount;
        if (packet -> referenceCount == 0)
          enet_packet_destroy (packet);
    }

    ++ peer -> mtuDiscovery.stats.resegmentations;
    peer -> mtuDiscovery.resegmentPending = 0;
}

void
enet_mtu_before_send (ENetHost * host, ENetPeer * peer)
{
    if (! host -> mtuConfig.enabled)
      return;

    if (peer -> mtuDiscovery.resegmentPending)
      enet_mtu_resegment (peer);
}

void
enet_mtu_pump (ENetHost * host, ENetPeer * peer, enet_uint32 now)
{
    ENetMtuDiscovery * discovery = & peer -> mtuDiscovery;
    enet_uint32 candidate;

    if (! host -> mtuConfig.enabled)
      return;

    /* Only run once a peer is associated with a connection (its connectID and
     * outgoing peer id are needed for the probe cookie and routing). Probes
     * are therefore never sent before the handshake has associated the peer. */
    if (peer -> state == ENET_PEER_STATE_DISCONNECTED ||
        peer -> state == ENET_PEER_STATE_ZOMBIE ||
        peer -> outgoingPeerID >= ENET_PROTOCOL_MAXIMUM_PEER_ID)
      return;

    if (discovery -> state == ENET_MTU_STATE_PROBING)
    {
        if (discovery -> nextProbeTime != 0 && ENET_TIME_LESS (now, discovery -> nextProbeTime))
          return;

        if (discovery -> probeAttempts + 1 < host -> mtuConfig.maxProbeAttempts)
        {
            ++ discovery -> probeAttempts;
            enet_mtu_send_probe (host, peer, discovery -> probeMtu, now);
            return;
        }

        enet_mtu_probe_failed (host, peer, now);
        return;
    }

    if (discovery -> state == ENET_MTU_STATE_BLACK_HOLE)
    {
        if (discovery -> blackHoleUntil != 0 && ENET_TIME_LESS (now, discovery -> blackHoleUntil))
          return;

        /* Retry the floor first; only leave the black-hole state once it acks. */
        discovery -> state = ENET_MTU_STATE_IDLE;
        discovery -> probeLow = discovery -> baseMtu;
        discovery -> probeHigh = discovery -> maxMtu + 1;
        discovery -> probeAttempts = 0;
        discovery -> floorProbed = 0;
    }

    if (discovery -> state == ENET_MTU_STATE_CONVERGED)
    {
        if (discovery -> nextRevalidateTime == 0 ||
            ENET_TIME_LESS (now, discovery -> nextRevalidateTime))
          return;

        /* Revalidate the current MTU with a single probe; failure reopens the
         * search below the current value. */
        discovery -> probeAttempts = 0;
        discovery -> revalidating = 1;
        enet_mtu_send_probe (host, peer, peer -> mtu, now);
        return;
    }

    if (discovery -> nextProbeTime != 0 && ENET_TIME_LESS (now, discovery -> nextProbeTime))
      return;

    candidate = enet_mtu_next_candidate (peer);
    if (candidate != 0)
    {
        discovery -> probeAttempts = 0;
        discovery -> revalidating = 0;
        enet_mtu_send_probe (host, peer, candidate, now);
        return;
    }

    /* The binary search has converged. Before declaring the result, verify the
     * safe floor exactly once per search phase. On a healthy path this is a
     * single extra probe that always succeeds; on a total black hole it fails
     * and enet_mtu_probe_failed() moves the peer into back-off instead of
     * converging on an unusable MTU. */
    if (! discovery -> floorProbed)
    {
        discovery -> floorProbed = 1;
        discovery -> probeAttempts = 0;
        discovery -> revalidating = 0;
        enet_mtu_send_probe (host, peer, discovery -> baseMtu, now);
        return;
    }

    enet_mtu_converge (peer, now);
}

void
enet_mtu_handle_probe (ENetHost * host, ENetPeer * peer, const ENetProtocol * command)
{
    ENetBuffer buffer;
    ENetProtocolMtuAck * ack;
    enet_uint8 * data = host -> mtuProbeData;
    size_t headerSize;
    enet_uint32 probeMtu = ENET_NET_TO_HOST_32 (command -> mtuProbe.probeMtu);
    enet_uint32 nonce = ENET_NET_TO_HOST_32 (command -> mtuProbe.nonce);
    enet_uint32 cookie = ENET_NET_TO_HOST_32 (command -> mtuProbe.cookie);
    enet_uint32 expectedCookie;

    /* Probes are only meaningful on an associated peer whose connectID is part
     * of the cookie. Unknown peers are ignored silently. */
    if (peer == NULL || peer -> state == ENET_PEER_STATE_DISCONNECTED)
    {
        if (peer != NULL)
          ++ peer -> mtuDiscovery.stats.probesRejected;
        return;
    }

    if (probeMtu < ENET_PROTOCOL_MINIMUM_MTU || probeMtu > ENET_PROTOCOL_MAXIMUM_MTU)
    {
        ++ peer -> mtuDiscovery.stats.probesRejected;
        return;
    }

    expectedCookie = enet_mtu_cookie (peer, probeMtu, nonce);
    if (expectedCookie != cookie)
    {
        ++ peer -> mtuDiscovery.stats.probesRejected;
        enet_mtu_diag (peer, "rejected probe with bad cookie", probeMtu);
        return;
    }

    /* Authenticated probes are answered exactly once per received datagram and
     * only from the preallocated scratch buffer, so they cannot amplify traffic
     * nor allocate per probe. The ack datagram is padded to the same MTU so the
     * round trip proves both directions carry that size. */
    memset (data, 0, probeMtu);

    headerSize = enet_mtu_command_offset (host, peer, data);

    if (headerSize + sizeof (ENetProtocolMtuAck) > probeMtu)
    {
        ++ peer -> mtuDiscovery.stats.probesRejected;
        return;
    }

    ack = (ENetProtocolMtuAck *) (data + headerSize);
    ack -> header.command = ENET_PROTOCOL_COMMAND_MTU_ACK;
    ack -> header.channelID = 0xFF;
    ack -> header.reliableSequenceNumber = 0;
    ack -> cookie = ENET_HOST_TO_NET_32 (expectedCookie);
    ack -> probeMtu = ENET_HOST_TO_NET_32 (probeMtu);
    ack -> nonce = ENET_HOST_TO_NET_32 (nonce);

    enet_mtu_finalize_checksum (host, peer, data, probeMtu);

    buffer.data = data;
    buffer.dataLength = probeMtu;

    if (enet_socket_send (host -> socket, & peer -> address, & buffer, 1) < 0)
    {
        enet_mtu_diag (peer, "ack socket send failed", probeMtu);
        return;
    }

    host -> totalSentData += probeMtu;
    ++ host -> totalSentPackets;
    ++ peer -> mtuDiscovery.stats.acksSent;
}

void
enet_mtu_handle_ack (ENetHost * host, ENetPeer * peer, const ENetProtocol * command)
{
    ENetMtuDiscovery * discovery;
    enet_uint32 probeMtu, nonce, cookie, expectedCookie;

    if (peer == NULL || peer -> state == ENET_PEER_STATE_DISCONNECTED)
      return;

    discovery = & peer -> mtuDiscovery;

    probeMtu = ENET_NET_TO_HOST_32 (command -> mtuAck.probeMtu);
    nonce = ENET_NET_TO_HOST_32 (command -> mtuAck.nonce);
    cookie = ENET_NET_TO_HOST_32 (command -> mtuAck.cookie);

    expectedCookie = enet_mtu_cookie (peer, probeMtu, nonce);
    if (expectedCookie != cookie ||
        nonce != discovery -> probeNonce ||
        probeMtu != discovery -> probeMtu ||
        discovery -> state != ENET_MTU_STATE_PROBING)
    {
        ++ discovery -> stats.probesRejected;
        enet_mtu_diag (peer, "rejected stale or forged ack", probeMtu);
        return;
    }

    ++ discovery -> stats.probesAcked;

    /* A revalidation probe of the already-converged MTU: keep the value and
     * reschedule the next revalidation. */
    if (discovery -> revalidating)
    {
        discovery -> revalidating = 0;
        enet_mtu_converge (peer, host -> serviceTime);
        return;
    }

    if (probeMtu > discovery -> probeLow)
      discovery -> probeLow = probeMtu;

    enet_mtu_apply (peer, discovery -> probeLow);

    discovery -> state = ENET_MTU_STATE_IDLE;
    discovery -> probeMtu = 0;
    discovery -> probeAttempts = 0;
    discovery -> stats.currentProbeMtu = 0;
    discovery -> nextProbeTime = host -> serviceTime;
}

/* Called from the reliable-command timeout path. Repeated timeouts while probes
 * are healthy usually mean ordinary congestion, but a timeout coinciding with
 * an active (or recently failed) large-MTU probe is a strong black-hole signal:
 * force a conservative step down and reopen the search without disconnecting. */
void
enet_mtu_note_suspicious_timeout (ENetPeer * peer)
{
    ENetMtuDiscovery * discovery;
    enet_uint32 fallback;

    if (peer == NULL || ! peer -> host -> mtuConfig.enabled)
      return;

    if (peer -> state != ENET_PEER_STATE_CONNECTED &&
        peer -> state != ENET_PEER_STATE_DISCONNECT_LATER)
      return;

    discovery = & peer -> mtuDiscovery;

    if (peer -> mtu <= discovery -> baseMtu)
      return;

    fallback = enet_mtu_align (peer -> mtu / 2);
    if (fallback < discovery -> baseMtu)
      fallback = discovery -> baseMtu;
    if (fallback >= peer -> mtu)
      fallback = discovery -> baseMtu;

    enet_mtu_diag (peer, "suspicious timeout, stepping MTU down", fallback);

    discovery -> probeHigh = peer -> mtu;
    discovery -> probeLow = ENET_MIN (discovery -> probeLow, fallback);
    discovery -> state = ENET_MTU_STATE_IDLE;
    discovery -> probeMtu = 0;
    discovery -> probeAttempts = 0;
    discovery -> revalidating = 0;
    discovery -> floorProbed = 0;
    discovery -> nextProbeTime = peer -> host -> serviceTime;

    enet_mtu_apply (peer, fallback);
}

